{
  "title": "数据中心的迷雾",
  "scene": "霓虹闪烁的赛博朋克都市中，一个巨大的数据中心矗立在夜色中。建筑物的外壳由闪烁的LED灯组成，显示出企业标志性的LOGO。你站在一个紧闭的门前，门上的数字显示着一个授权码：12345。你身旁放着一台小型的加密设备，可以用来破解门锁。门后似乎隐藏着重要的信息。",
  "goal": "使用正确的工具破解门锁，进入数据中心的内部。",
  "clue": "授权码和加密设备。",
  "choices": [
    {"id": "A", "text": "尝试使用加密设备解码授权码", "outcome": "加密设备发出一阵嗡嗡声，屏幕显示出正确的授权码。你迅速输入并打开了门。门后是一条昏暗的走廊，你隐约看到远处有一台闪烁着红光的终端机。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "直接撞开大门", "outcome": "大门的锁相当坚固，你撞了几次都没能打开，反而引来了数据中心的安保人员。", "result": "fail", "next": "retry"},
    {"id": "C", "text": "仔细检查门上的授权码和加密设备", "outcome": "你注意到授权码和加密设备上都有轻微的划痕。你尝试用加密设备读取划痕，结果屏幕上显示出正确的授权码。你输入授权码打开了门。门后是一条昏暗的走廊，你隐约看到远处有一台闪烁着红光的终端机。", "result": "partial", "next": "next_level"}
  ]
}
